import{_ as a,o as i,c as t,a2 as s}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1785765821000}'),o={name:"guide/faq.md"};function l(r,e,n,h,d,p){return i(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="自签证书浏览器提示-不安全" tabindex="-1">自签证书浏览器提示&quot;不安全&quot; <a class="header-anchor" href="#自签证书浏览器提示-不安全" aria-label="Permalink to &quot;自签证书浏览器提示&quot;不安全&quot;&quot;">​</a></h2><p><code>localhost</code> 与公网 IP 使用自签证书，浏览器会提示&quot;证书颁发机构不受信任&quot;。解决方法：</p><ul><li>将 <code>config/ssl/cert.pem</code> 导入客户端&quot;受信任的根证书颁发机构&quot;；或</li><li>使用域名并通过 Let&#39;s Encrypt 申请可信证书，详见 <a href="/guide/https">HTTPS 与证书</a>。</li></ul><h2 id="websocket-连接失败" tabindex="-1">WebSocket 连接失败 <a class="header-anchor" href="#websocket-连接失败" aria-label="Permalink to &quot;WebSocket 连接失败&quot;">​</a></h2><p>确认反向代理（Nginx 等）已正确配置 WebSocket 升级头：</p><div class="language-nginx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">nginx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">proxy_http_version </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Upgrade $http_upgrade;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Connection </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;upgrade&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><h2 id="webrtc-无法建立连接" tabindex="-1">WebRTC 无法建立连接 <a class="header-anchor" href="#webrtc-无法建立连接" aria-label="Permalink to &quot;WebRTC 无法建立连接&quot;">​</a></h2><p>WebRTC 的 <code>getUserMedia</code> 要求 HTTPS 访问。生产环境请配置 SSL 证书。若双方处于严格 NAT 之后，可能需要部署 TURN 服务器（如 coturn）。</p><h2 id="数据库说明" tabindex="-1">数据库说明 <a class="header-anchor" href="#数据库说明" aria-label="Permalink to &quot;数据库说明&quot;">​</a></h2><p>后端使用 TypeORM + sql.js（wasm 版 SQLite）持久化，纯 JS 实现、无原生模块——单文件 exe 版可在任意平台直接运行，无需编译。数据库文件为标准 SQLite 格式（<code>config/dev.sqlite</code>），可用常规 SQLite 工具查看。</p><p>支持可选 PostgreSQL，配置方式见<a href="/dev/env">环境变量</a>。</p><h2 id="bilibili-解析失败" tabindex="-1">Bilibili 解析失败 <a class="header-anchor" href="#bilibili-解析失败" aria-label="Permalink to &quot;Bilibili 解析失败&quot;">​</a></h2><ul><li>检查后端是否正确携带 Referer 等请求头。</li><li>封面与视频地址通过后端代理获取，避免 CORS 与防盗链问题。</li><li>大会员专享内容需在后台配置有效的 Bilibili 登录凭证，或使用 <a href="/features/video-sources#zviewercli-本地代理">ZViewerCLI 本地代理</a>。</li></ul><h2 id="房主离线后房间会怎样" tabindex="-1">房主离线后房间会怎样 <a class="header-anchor" href="#房主离线后房间会怎样" aria-label="Permalink to &quot;房主离线后房间会怎样&quot;">​</a></h2><p>房主短暂断线后，由服务器继续广播当前播放状态，观众无需中断观看（播放记忆功能）；房主离线超时 10 分钟自动关房，期间观众可自由控制。</p><h2 id="如何更改默认的-root-密码" tabindex="-1">如何更改默认的 root 密码 <a class="header-anchor" href="#如何更改默认的-root-密码" aria-label="Permalink to &quot;如何更改默认的 root 密码&quot;">​</a></h2><p>使用 <code>root</code> / <code>root</code> 登录后，进入个人资料页修改密码；管理员也可在管理后台用户管理中对用户进行管理。</p><h2 id="更新机制" tabindex="-1">更新机制 <a class="header-anchor" href="#更新机制" aria-label="Permalink to &quot;更新机制&quot;">​</a></h2><p>系统支持从 GitHub Releases 自动检测并应用更新，也支持手动上传压缩包更新。管理员可在管理后台控制是否接收预发布版（main 分支自动构建）的更新，详见<a href="/guide/deployment#更新机制">部署方式</a>。</p>`,20)])])}const k=a(o,[["render",l]]);export{u as __pageData,k as default};
